// seqtk sample: subsample sequences (fraction or fixed number).
#include "common.h"
#include <unistd.h>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <random>
#include <vector>
#include <unordered_set>

static int sample_usage() {
    fprintf(stderr, "\n");
    fprintf(stderr, "Usage:   seqtk sample [-2] [-s seed=11] <in.fa> <frac>|<number>\n");
    fprintf(stderr, "\n");
    fprintf(stderr, "Options: -s INT       RNG seed [11]\n");
    fprintf(stderr, "         -2           2-pass mode: twice as slow but with much reduced memory\n");
    fprintf(stderr, "\n");
    return 1;
}

int cmd_sample(int argc, char** argv) {
    int c, is_2pass = 0;
    long long seed = 11;
    while ((c = getopt(argc, argv, "s:2")) >= 0) {
        if (c == 's') seed = atoll(optarg);
        else if (c == '2') is_2pass = 1;
    }
    if (argc - optind < 2) return sample_usage();
    const char* fn = argv[optind];
    double x = atof(argv[optind + 1]);
    std::mt19937_64 g((uint64_t)seed);
    SeqRecord r;
    if (x < 1.0) { // sample a fraction
        if (is_2pass)
            fprintf(stderr, "[W::stk_sample] when sampling a fraction, option -2 is ignored.");
        SeqFile sf(fn);
        if (!sf.is_open()) {
            fprintf(stderr, "[E::stk_sample] failed to open the input file/stream.\n");
            return 1;
        }
        while (sf.next(r) == 1) {
            double u = rand_uniform(g);
            if (u < x) print_record(stdout, r, 0, false);
        }
    } else if (!is_2pass) { // reservoir sampling, keeping records in memory
        long n = (long)(x + .499);
        SeqFile sf(fn);
        if (!sf.is_open()) {
            fprintf(stderr, "[E::stk_sample] failed to open the input file/stream.\n");
            return 1;
        }
        std::vector<SeqRecord> buf;
        long i = 0;
        while (sf.next(r) == 1) {
            double u = rand_uniform(g);
            if (i < n) buf.push_back(r);
            else {
                long j = (long)(u * (i + 1));
                if (j < n) buf[j] = r;
            }
            ++i;
        }
        for (long k = 0; k < (long)buf.size(); ++k)
            print_record(stdout, buf[k], 0, false);
    } else { // 2-pass mode: reservoir over indices, then print in input order
        long n = (long)(x + .499);
        if (strcmp(fn, "-") == 0) {
            fprintf(stderr, "[E::stk_sample] in the 2-pass mode, the input cannot be STDIN.\n");
            return 1;
        }
        std::unordered_set<long> sel;
        {
            SeqFile sf(fn);
            if (!sf.is_open()) {
                fprintf(stderr, "[E::stk_sample] failed to open the input file/stream.\n");
                return 1;
            }
            std::vector<long> buf;
            long i = 0;
            while (sf.next(r) == 1) {
                double u = rand_uniform(g);
                if (i < n) buf.push_back(i);
                else {
                    long j = (long)(u * (i + 1));
                    if (j < n) buf[j] = i;
                }
                ++i;
            }
            sel.insert(buf.begin(), buf.end());
        }
        SeqFile sf(fn);
        if (!sf.is_open()) {
            fprintf(stderr, "[E::stk_sample] failed to open the input file/stream.\n");
            return 1;
        }
        long i = 0;
        while (sf.next(r) == 1) {
            if (sel.count(i)) print_record(stdout, r, 0, false);
            ++i;
        }
    }
    return 0;
}

